import React from 'react';
import clsx from 'clsx';
import './AcidGradientButton.css';

export interface AcidGradientButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: 'default' | 'outline' | 'ghost';
    size?: 'sm' | 'md' | 'lg' | 'xl';
    animationSpeed?: 'fast' | 'normal' | 'slow';
    gradientType?: 'orange' | 'cool' | 'purple';
}

export const AcidGradientButton = ({
    children,
    className,
    variant = 'default',
    size = 'md',
    animationSpeed = 'normal',
    gradientType = 'orange',
    ...props
}: AcidGradientButtonProps) => {
    return (
        <button
            className={clsx(
                'ac-gradient-btn',
                `ac-btn-${variant}`,
                `ac-btn-${size}`,
                `ac-anim-${animationSpeed}`,
                `ac-grad-${gradientType}`,
                className
            )}
            {...props}
        >
            <span className="ac-btn-content">{children}</span>
            <div className="ac-btn-gradient-overlay" />
        </button>
    );
};

.ac-gradient-btn {
    position: relative;
    border: none;
    border-radius: 9999px;
    cursor: pointer;
    overflow: hidden;
    color: #fff;
    font-family: var(--font-mono);
    font-weight: 600;
    transition: transform 0.2s;
    background: #000;
}

.ac-gradient-btn:active {
    transform: scale(0.96);
}

.ac-btn-sm {
    padding: 0.5rem 1rem;
    font-size: 0.75rem;
}

.ac-btn-md {
    padding: 0.75rem 1.75rem;
    font-size: 0.875rem;
}

.ac-btn-lg {
    padding: 1rem 2.5rem;
    font-size: 1rem;
}

.ac-btn-xl {
    padding: 1.25rem 3.5rem;
    font-size: 1.25rem;
}

.ac-btn-gradient-overlay {
    position: absolute;
    inset: -50%;
    background: conic-gradient(transparent,
            var(--grad-color-1),
            var(--grad-color-2),
            transparent);
    animation: rotate var(--anim-duration) linear infinite;
    z-index: 1;
}

.ac-btn-content {
    position: relative;
    z-index: 2;
    background: #000;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: inherit;
    margin: 2px;
}

/* Gradients */
.ac-grad-orange {
    --grad-color-1: #f97316;
    --grad-color-2: #ec4899;
}

.ac-grad-cool {
    --grad-color-1: #3b82f6;
    --grad-color-2: #22c55e;
}

.ac-grad-purple {
    --grad-color-1: #8b5cf6;
    --grad-color-2: #ec4899;
}

/* Speeds */
.ac-anim-fast {
    --anim-duration: 0.5s;
}

.ac-anim-normal {
    --anim-duration: 2s;
}

.ac-anim-slow {
    --anim-duration: 5s;
}

@keyframes rotate {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}
